import java.util.*;

class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            List<Integer> level = new ArrayList<>();

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            result.add(level);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        dfs(root, 0, result);
        return result;
    }

    private void dfs(TreeNode node, int level, List<List<Integer>> result) {
        if (node == null) {
            return;
        }
        if (level == result.size()) {
            result.add(new ArrayList<>());
        }

        result.get(level).add(node.val);
        dfs(node.left, level + 1, result);
        dfs(node.right, level + 1, result);
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Queue<NodeLevel> queue = new ArrayDeque<>();
        queue.offer(new NodeLevel(root, 0));

        while (!queue.isEmpty()) {
            NodeLevel current = queue.poll();
            if (result.size() == current.level) {
                result.add(new ArrayList<>());
            }
            result.get(current.level).add(current.node.val);

            if (current.node.left != null) {
                queue.offer(new NodeLevel(current.node.left, current.level + 1));
            }
            if (current.node.right != null) {
                queue.offer(new NodeLevel(current.node.right, current.level + 1));
            }
        }
        return result;
    }

    private static class NodeLevel {
        TreeNode node;
        int level;

        NodeLevel(TreeNode node, int level) {
            this.node = node;
            this.level = level;
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        List<TreeNode> current = new ArrayList<>();
        current.add(root);

        while (!current.isEmpty()) {
            List<Integer> level = new ArrayList<>();
            List<TreeNode> next = new ArrayList<>();

            for (TreeNode node : current) {
                level.add(node.val);
                if (node.left != null) {
                    next.add(node.left);
                }
                if (node.right != null) {
                    next.add(node.right);
                }
            }

            result.add(level);
            current = next;
        }
        return result;
    }
}
